import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs';
import {defaultVideoId,getYouTubeId,getHlsUrl,createPlayerController,youtubeErrorMessage} from './public/teste/tesla/player-core.js';
test('YouTube IDs are parsed only from allowed services, including a shared app link',()=>{
 for(const value of [defaultVideoId,'https://video.example.invalid/app#/watch/3HOKK2MTtNQ','https://www.youtube.com/watch?v=3HOKK2MTtNQ','https://youtu.be/3HOKK2MTtNQ?t=12','https://m.youtube.com/shorts/3HOKK2MTtNQ'])assert.equal(getYouTubeId(value),defaultVideoId);
 for(const value of ['javascript:alert(1)','https://youtube.com.evil.invalid/watch?v=3HOKK2MTtNQ','https://evil.invalid/#/watch/3HOKK2MTtNQ','https://user:secret@youtube.com/watch?v=3HOKK2MTtNQ','not a video'])assert.equal(getYouTubeId(value),null);
});
test('HLS accepts HTTPS provider paths and query credentials without persistence; rejects unsafe URL schemes',()=>{
 const url='https://provider.example.invalid/user/secret/channel.m3u8?token=PRIVATE';assert.equal(getHlsUrl(url),url);
 for(const value of ['http://provider.example.invalid/c.m3u8','javascript:alert(1)','file:///etc/passwd','data:video/mp4,','https://user:secret@provider.example.invalid/c.m3u8','invalid'])assert.equal(getHlsUrl(value),null);
});
function fixture({native=false,delayedHls}={}){
 const events={},instances=[],players=[],messages=[],sources=[],video={hidden:true,src:'',paused:0,loads:0,pause(){this.paused++},load(){this.loads++},removeAttribute(){this.src=''},canPlayType(){return native?'maybe':''},addEventListener(k,v){events[k]=v},removeEventListener(k){delete events[k]}},mount={hidden:true,children:[],ownerDocument:{createElement(){return{}}},append(x){this.children.push(x)},replaceChildren(){this.children=[]}};
 class Hls{static Events={ERROR:'error',MANIFEST_PARSED:'parsed'};static isSupported(){return true}constructor(options){this.options=options;this.events={};this.destroyed=false;this.starts=0;instances.push(this)}on(k,fn){this.events[k]=fn}loadSource(url){this.url=url}attachMedia(v){this.video=v}startLoad(){this.starts++}destroy(){this.destroyed=true}}
 const api={Player:class{constructor(node,options){this.options=options;this.node=node;this.destroyed=false;players.push(this)}destroy(){this.destroyed=true}}};
 const controller=createPlayerController({video,mount,origin:'https://www.affinityfc.org',loadHls:()=>delayedHls||Promise.resolve(Hls),loadYouTube:async()=>api,onStatus:(...args)=>messages.push(args),onSource:(...args)=>sources.push(args)});
 return{controller,video,mount,events,instances,players,messages,Hls,sources};
}
test('three alternating source changes destroy previous players and never autoplay',async()=>{const f=fixture();await f.controller.youtube(defaultVideoId);assert.equal(f.players[0].options.playerVars.autoplay,0);await f.controller.hls('https://provider.example.invalid/c.m3u8');assert(f.players[0].destroyed);assert.equal(f.instances[0].options.autoStartLoad,false);assert.equal(f.instances[0].starts,0);f.events.play();assert.equal(f.instances[0].starts,1);await f.controller.youtube(defaultVideoId);assert(f.instances[0].destroyed);await f.controller.hls('https://provider.example.invalid/second.m3u8');assert(f.players[1].destroyed);assert.equal(f.controller.source,'hls');f.controller.dispose();assert(f.instances[1].destroyed);assert.equal(f.video.src,'');assert(f.video.hidden);assert.equal(f.mount.children.length,0);assert.equal(Object.keys(f.events).length,0);});
test('native HLS is preferred and no JavaScript HLS library is needed on supporting browsers',async()=>{const f=fixture({native:true});await f.controller.hls('https://provider.example.invalid/native.m3u8');assert.equal(f.video.src,'https://provider.example.invalid/native.m3u8');assert.equal(f.instances.length,0);f.controller.stop();assert.equal(f.video.src,'');});
test('fatal HLS errors and YouTube embedding errors show a safe failure without provider credentials',async()=>{const f=fixture(),url='https://provider.example.invalid/SECRET.m3u8?password=PRIVATE';await f.controller.hls(url);const instance=f.instances[0];instance.events.error('error',{fatal:true,url,details:'SECRET'});assert(instance.destroyed);assert.equal(f.controller.source,null);assert(!JSON.stringify(f.messages).includes('SECRET'));assert(!JSON.stringify(f.messages).includes('PRIVATE'));await f.controller.youtube(defaultVideoId);f.players[0].options.events.onError({data:150});assert.match(f.messages.at(-1)[0],/não permite/);assert.match(youtubeErrorMessage(153),/não autorizou/);assert.match(youtubeErrorMessage(100),/privado/);});
test('an old asynchronous library load cannot resurrect playback after switching or leaving',async()=>{let resolve;const pending=new Promise(r=>resolve=r),f=fixture({delayedHls:pending});const first=f.controller.hls('https://provider.example.invalid/private.m3u8');await f.controller.youtube(defaultVideoId);resolve(f.Hls);await first;assert.equal(f.instances.length,0);assert.equal(f.controller.source,'youtube');f.controller.dispose();assert.equal(f.controller.source,null);});
test('route has official Netflix/fallback links, local pinned HLS and no logging/storage of IPTV URLs',()=>{const base=new URL('./public/teste/tesla/',import.meta.url),html=fs.readFileSync(new URL('index.html',base),'utf8'),js=fs.readFileSync(new URL('player.js',base),'utf8'),core=fs.readFileSync(new URL('player-core.js',base),'utf8');assert(html.includes('href="https://www.netflix.com/"'));assert(html.includes('Abrir no YouTube'));assert(html.includes('3HOKK2MTtNQ'));assert(!/autoplay(?:=|\s)/i.test(html));assert(!/localStorage|sessionStorage|indexedDB|console\.|sendBeacon|analytics/.test(js+core));assert(js.includes("fetch('/api/media/youtube-search'"));assert(js.includes("import('./hls-1.7.4.mjs')"));assert(js.includes("addEventListener('pagehide'"));assert(html.includes('ainda não foi validada'));const dependency=fs.readFileSync(new URL('./dependencies/node_modules/hls.js/dist/hls.min.mjs',import.meta.url),'utf8').replace(/^\/\/# sourceMappingURL=.*$/gm,'');assert.equal(fs.readFileSync(new URL('hls-1.7.4.mjs',base),'utf8'),dependency);});
